customize.css:
/* A one-page dark look: a grey-to-black sky behind a huge, widely spaced uppercase title, rounded type, teal buttons, dark bordered cards.
   Written for this blog's own markup from the page's layout and palette; no stylesheet or font was copied. */
:root{color-scheme:dark;--fg:rgba(255,255,255,.78);--bg:#000;--link:#64a19d;--muted:rgba(255,255,255,.5);--rule:#222;--code:#0d0d0d;--teal:#64a19d;--card:#0b0b0b;--font:ui-rounded,"SF Pro Rounded","Nunito","Varela Round",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;--heading-font:ui-rounded,"SF Pro Rounded","Nunito","Varela Round",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
html{background:#000}
body{background:linear-gradient(to bottom,#858585 0,#4a4a4a 300px,#161616 640px,#000 920px) no-repeat #000;color:var(--fg);font-family:var(--font);line-height:1.7;overflow-x:hidden}
.wrap{max-width:1000px;padding:0 1.5rem 4rem}
a{color:var(--teal);text-decoration:none}
a:hover{color:#8fc4c0;text-decoration:underline}
header.site{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:.5rem 1.5rem;margin:0;padding:1.6rem 0;border:0}
header.site a.brand{color:rgba(255,255,255,.85);font-size:1.15rem;font-weight:700;letter-spacing:.02em;text-decoration:none}
header.site a.brand::before{content:none}
header.site nav{display:flex;flex-wrap:wrap;gap:.2rem 2rem}
header.site nav a{margin:0;color:rgba(255,255,255,.7);font-size:.9rem;font-weight:600;letter-spacing:.04em;text-decoration:none}
header.site nav a::before{content:none}
header.site nav a:hover{color:#fff}
h1,h2,h3{color:#fff;font-weight:700;line-height:1.15}
h1::before,h2::before,h3::before,ul.posts h2::before{content:none}
body>.wrap>h1{margin:0;padding:6.5rem 0 1rem;text-align:center;font-size:clamp(2.4rem,9vw,6rem);letter-spacing:.35em;text-transform:uppercase;background:linear-gradient(to bottom,#fff 30%,#9a9a9a 100%);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent;padding-left:.35em}
body>.wrap>h1+.meta{margin:0 auto 3.5rem;padding:0 0 5rem;max-width:30rem;text-align:center;color:rgba(255,255,255,.7);font-size:1.15rem;letter-spacing:.02em;text-transform:none;font-weight:600}
h2{font-size:1.5rem}
h3{font-size:1.2rem}
.meta{color:var(--muted);font-size:.72rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase}
.meta .tag{display:inline-block;margin:0 0 0 .6rem;padding:.2rem .6rem;border:1px solid rgba(100,161,157,.5);border-radius:3px;color:var(--teal);font-size:.62rem;letter-spacing:.12em;text-decoration:none}
.meta .tag:hover{background:var(--teal);color:#000;text-decoration:none}
ul.posts{list-style:none;padding:0;margin:0 0 2rem;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem}
ul.posts li{display:flex;flex-direction:column;margin:0;padding:1.6rem 1.6rem 1.4rem;background:var(--card);border:1px solid var(--rule);border-radius:4px;box-shadow:0 .25rem 1.5rem rgba(0,0,0,.5);transition:border-color .2s,transform .2s}
ul.posts li:hover{border-color:var(--teal);transform:translateY(-2px)}
ul.posts .thumb{order:0;display:block;aspect-ratio:16/9;overflow:hidden;margin:-1.6rem -1.6rem 1.2rem;background:#111}
ul.posts .thumb img{width:100%;height:100%;object-fit:cover;border:0;border-radius:0;filter:grayscale(1)}
ul.posts .meta{order:1;margin:0 0 .6rem}
ul.posts h2{order:2;margin:0 0 .4rem;font-size:1.25rem;letter-spacing:.02em;line-height:1.3}
ul.posts h2 a{color:#fff;text-decoration:none}
ul.posts h2 a:hover{color:var(--teal)}
ul.posts p{order:3;margin:0;color:rgba(255,255,255,.6);font-size:.95rem}
article{max-width:44rem;margin:2rem auto 0}
article h1{margin:0 0 .4em;font-size:clamp(2rem,6vw,3.2rem);letter-spacing:.08em;text-transform:uppercase;background:none;-webkit-text-fill-color:#fff;color:#fff;padding:0;text-align:left}
article a{overflow-wrap:anywhere}
img{border:0;border-radius:4px}
blockquote{margin:1.6em 0;padding:.3em 1.4em;border-left:3px solid var(--teal);color:rgba(255,255,255,.7);font-size:1.1em}
pre{background:var(--code);border:1px solid var(--rule);border-radius:4px}
code{background:var(--code);border-radius:3px;color:#cfe7e5}
pre code{background:none;color:inherit}
th{background:#111;color:#fff}
th,td{border-color:var(--rule)}
hr{border:0;border-top:1px solid var(--rule)}
.post-nav,.navigation.pagination .nav-links{display:flex;justify-content:space-between;gap:1rem;margin-top:2.5rem}
.post-nav a,.navigation.pagination a{max-width:48%;padding:.8rem 1.6rem;background:var(--teal);color:#000;font-size:.72rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;text-decoration:none;border-radius:4px;box-shadow:0 .25rem .5rem rgba(0,0,0,.4)}
.post-nav a:hover,.navigation.pagination a:hover{background:#8fc4c0}
form[role=search] input,form.subscribe input{padding:.7rem 1rem;border:1px solid #333;border-radius:4px;background:#0b0b0b;color:#fff}
form[role=search] button,form.subscribe button{padding:.7rem 1.5rem;border:0;border-radius:4px;background:var(--teal);color:#000;font-weight:700;letter-spacing:.12em;text-transform:uppercase;cursor:pointer}
footer.site{margin:3rem 0 0;padding:1.6rem 0;border:0;border-top:1px solid var(--rule);color:rgba(255,255,255,.4);font-size:.8rem;letter-spacing:.04em;text-align:center}
footer.site a{color:rgba(255,255,255,.6)}
::selection{background:var(--teal);color:#000}
@media (max-width:760px){ul.posts{grid-template-columns:1fr}body>.wrap>h1{letter-spacing:.18em;padding-top:4rem}body>.wrap>h1+.meta{padding-bottom:3rem}}
@media (prefers-reduced-motion:reduce){ul.posts li{transition:none}ul.posts li:hover{transform:none}}
